package sfnt

// This file builds deterministic, self-contained SFNT fonts entirely in
// memory. Nothing here reads from the network or from the host's font
// directories. The builders are used by the structured fault-injection gate
// (fuzz_gate_test.go) and the golden-output tests (fuzz_golden_test.go).
//
// All randomness flows from a single fixed-seed splitMix64 stream so that the
// generated bytes, and therefore the JSONL summary, are reproducible.

import (
	"encoding/binary"
	"sort"
)

// splitMix64 is a deterministic pseudo-random source. It is intentionally
// independent of math/rand so the generated corpus does not change across Go
// releases or runtime seeding policies.
type splitMix64 struct {
	state uint64
}

func newSplitMix64(seed uint64) *splitMix64 { return &splitMix64{state: seed} }

func (r *splitMix64) next() uint64 {
	r.state += 0x9e3779b97f4a7c15
	z := r.state
	z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9
	z = (z ^ (z >> 27)) * 0x94d049bb133111eb
	return z ^ (z >> 31)
}

// u16n returns a pseudo-random uint16 in [0, n). n must be non-zero.
func (r *splitMix64) u16n(n uint16) uint16 {
	if n == 0 {
		return 0
	}
	return uint16(r.next() % uint64(n))
}

func putU16(b []byte, v uint16) { binary.BigEndian.PutUint16(b, v) }
func putU32(b []byte, v uint32) { binary.BigEndian.PutUint32(b, v) }

// i16 reinterprets a signed 16-bit value as its unsigned wire representation.
func i16(v int16) uint16         { return uint16(v) }
func tagBytes(tag string) []byte { return []byte(tag) }

// fontTables is an ordered collection of named SFNT tables keyed by their
// four-byte tag.
type fontTables map[string][]byte

func (t fontTables) sortedTags() []string {
	tags := make([]string, 0, len(t))
	for tag := range t {
		tags = append(tags, tag)
	}
	sort.Strings(tags)
	return tags
}

// buildSFNT packs the tables into a single sfnt font. The offset table and
// table records are laid out exactly as the OpenType specification requires:
// records are sorted ascending by tag and every table starts on a 4-byte
// boundary. magic selects the sfnt version: 0x00010000 (TrueType) or
// 0x4f54544f ("OTTO", PostScript/CFF).
//
// base is the file offset at which the font will be embedded. It is added to
// every table-record offset and is zero for a stand-alone font. The returned
// slice always starts at the sfnt header; the caller places it at base.
func buildSFNT(tables fontTables, magic uint32, base uint32) []byte {
	tags := tables.sortedTags()
	headerLen := 12 + 16*len(tags)
	offset := headerLen

	type placement struct {
		tag    string
		offset uint32
		data   []byte
	}
	placements := make([]placement, len(tags))
	for i, tag := range tags {
		data := tables[tag]
		placements[i] = placement{tag: tag, offset: uint32(offset), data: data}
		offset += len(data)
		offset = (offset + 3) &^ 3
	}

	out := make([]byte, offset)
	putU32(out[0:], magic)
	putU16(out[4:], uint16(len(tags)))
	// searchRange, entrySelector and rangeShift are informational; the sfnt
	// package ignores them, but compute them correctly for realism.
	entrySelector := uint16(0)
	for (1 << (entrySelector + 1)) <= len(tags) {
		entrySelector++
	}
	searchRange := uint16(16 * (1 << entrySelector))
	rangeShift := uint16(16*len(tags)) - searchRange
	putU16(out[6:], searchRange)
	putU16(out[8:], entrySelector)
	putU16(out[10:], rangeShift)

	for i, p := range placements {
		rec := out[12+16*i:]
		copy(rec[0:4], p.tag)
		putU32(rec[4:8], 0) // checksum is not validated by the sfnt package.
		putU32(rec[8:12], base+p.offset)
		putU32(rec[12:16], uint32(len(p.data)))
		copy(out[p.offset:], p.data)
	}
	return out
}

// buildTTC wraps one or more complete sfnt fonts in a "ttcf" collection
// header. Each embedded font is rebuilt with collection-relative table offsets
// via buildSFNT, matching how real TTC/OTC files store absolute offsets.
func buildTTC(fontSpecs []ttcFontSpec) []byte {
	headerLen := (12 + 4*len(fontSpecs) + 3) &^ 3
	offset := headerLen
	type placement struct {
		data   []byte
		offset uint32
	}
	placements := make([]placement, len(fontSpecs))
	for i, spec := range fontSpecs {
		data := buildSFNT(spec.tables, spec.magic, uint32(offset))
		placements[i] = placement{data: data, offset: uint32(offset)}
		offset += len(data)
		offset = (offset + 3) &^ 3
	}
	out := make([]byte, offset)
	copy(out[0:4], "ttcf")
	putU32(out[4:8], 0x00010000) // TTC version 1.0.
	putU32(out[8:12], uint32(len(fontSpecs)))
	for i, p := range placements {
		putU32(out[12+4*i:], p.offset)
	}
	for _, p := range placements {
		copy(out[p.offset:], p.data)
	}
	return out
}

// ttcFontSpec is one member font of a collection: its tables and sfnt magic.
type ttcFontSpec struct {
	tables fontTables
	magic  uint32
}

// minimalFontOptions controls the tables and glyph count produced by
// buildMinimalTrueType. Zero-valued booleans add the standard required tables.
type minimalFontOptions struct {
	numGlyphs    int
	compound     bool   // glyph 1 is a compound glyph referencing glyph 2.
	addKern      bool   // add a valid version-0 kern table.
	addGPOS      bool   // add a valid PairPos-format-1 GPOS table.
	gposSubtable []byte // override the GPOS PairPos subtable (when addGPOS).
}

// minimalTrueTypeTables builds the table set for a minimal valid TrueType
// font. See buildMinimalTrueType for the glyph and cmap conventions.
func minimalTrueTypeTables(opts minimalFontOptions) fontTables {
	numGlyphs := opts.numGlyphs
	if numGlyphs < 1 {
		numGlyphs = 1
	}
	if opts.compound && numGlyphs < 3 {
		numGlyphs = 3
	}

	tables := fontTables{}
	tables["OS/2"] = buildOS2()
	tables["cmap"] = buildCmapFormat4()
	tables["glyf"], tables["loca"] = buildGlyfAndLoca(numGlyphs, opts.compound)
	tables["head"] = buildHead()
	tables["hhea"] = buildHhea(numGlyphs)
	tables["hmtx"] = buildHmtx(numGlyphs)
	tables["maxp"] = buildMaxp(numGlyphs)
	tables["name"] = buildName()
	tables["post"] = buildPost()
	if opts.addKern {
		tables["kern"] = buildKern()
	}
	if opts.addGPOS {
		tables["GPOS"] = buildGPOS(opts.gposSubtable)
	}
	return tables
}

// buildMinimalTrueType builds a fully valid TrueType font that Parse accepts.
// It contains:
//   - glyph 0: .notdef (empty),
//   - glyph 1: a simple 4-point square outline (or a compound glyph),
//   - glyph 2 (only when compound): the square outline referenced by glyph 1,
//
// rune 'A' (U+0041) maps to glyph 1 and 'B' (U+0042) maps to glyph 2 when
// present. The font uses long (indexToLocFormat == 1) loca entries.
func buildMinimalTrueType(opts minimalFontOptions) []byte {
	return buildSFNT(minimalTrueTypeTables(opts), 0x00010000, 0)
}

func buildHead() []byte {
	b := make([]byte, 54)
	putU32(b[0:4], 0x00010000) // table version.
	putU32(b[4:8], 0x00005000) // fontRevision 0.5.
	putU32(b[12:16], 0x5f0f3cf5)
	putU16(b[18:20], 2048) // unitsPerEm.
	// b[24:32] created/modified dates left zero.
	// xMin, yMin, xMax, yMax at offsets 36, 38, 40, 42.
	putU16(b[36:38], 0)
	putU16(b[38:40], 0)
	putU16(b[40:42], 600)
	putU16(b[42:44], 700)
	putU16(b[48:50], 0)
	putU16(b[50:52], 1) // indexToLocFormat = 1 (long).
	return b
}

func buildMaxp(numGlyphs int) []byte {
	b := make([]byte, 32)
	putU32(b[0:4], 0x00010000) // maxp version 1.0.
	putU16(b[4:6], uint16(numGlyphs))
	return b
}

func buildHhea(numGlyphs int) []byte {
	b := make([]byte, 36)
	putU32(b[0:4], 0x00010000)
	putU16(b[4:6], 1800)  // ascent.
	putU16(b[6:8], 0x200) // descent stored as uint16 (-200).
	b[6] = 0xff
	b[7] = 0x38
	putU16(b[8:10], 0)                  // lineGap.
	putU16(b[34:36], uint16(numGlyphs)) // numHMetrics (must be <= numGlyphs).
	return b
}

func buildHmtx(numGlyphs int) []byte {
	// One long horizontal metric per glyph: advanceWidth 600, lsb 0.
	b := make([]byte, 4*numGlyphs)
	for i := 0; i < numGlyphs; i++ {
		putU16(b[4*i:4*i+2], 600)
		putU16(b[4*i+2:4*i+4], 0)
	}
	return b
}

func buildOS2() []byte {
	b := make([]byte, 96)
	putU16(b[0:2], 4)      // OS/2 version 4, so xHeight/capHeight are read directly.
	putU16(b[86:88], 1000) // sXHeight.
	putU16(b[88:90], 1400) // sCapHeight.
	return b
}

func buildPost() []byte {
	b := make([]byte, 32)
	putU32(b[0:4], 0x00030000) // post format 3.0: no glyph names.
	return b
}

// buildName builds a name table with a single Macintosh-Roman family-name
// record ("FuzzFont") at NameID 1.
func buildName() []byte {
	family := []byte("FuzzFont")
	const headerSize, entrySize = 6, 12
	stringOffset := headerSize + entrySize // one record immediately follows.
	b := make([]byte, stringOffset+len(family))
	putU16(b[0:2], 0) // format.
	putU16(b[2:4], 1) // count.
	putU16(b[4:6], uint16(stringOffset))
	rec := b[headerSize:]
	putU16(rec[0:2], pidMacintosh)
	putU16(rec[2:4], psidMacintoshRoman)
	putU16(rec[4:6], 0) // language ID.
	putU16(rec[6:8], uint16(NameIDFamily))
	putU16(rec[8:10], uint16(len(family)))
	putU16(rec[10:12], 0) // offset relative to stringOffset.
	copy(b[stringOffset:], family)
	return b
}

// buildCmapFormat4 builds a cmap table containing one Windows Unicode BMP
// subtable in format 4. It maps 'A' (U+0041) -> glyph 1 and 'B' (U+0042) ->
// glyph 2 via two single-rune segments with non-zero glyphIdArray entries.
func buildCmapFormat4() []byte {
	// Format 4 subtable layout after the 14-byte header:
	//	endCode[segCount], reservedPad, startCode[segCount],
	//	idDelta[segCount], idRangeOffset[segCount], glyphIdArray[...].
	segCount := 2
	// Compute concrete array offsets first and derive the subtable length from
	// them, instead of hand-counting the format-4 layout.
	offEndCode := 14
	offReserved := offEndCode + 2*segCount
	offStartCode := offReserved + 2
	offIDelta := offStartCode + 2*segCount
	offIRangeOffset := offIDelta + 2*segCount
	offGlyphArray := offIRangeOffset + 2*segCount
	subLen := offGlyphArray + 2*segCount
	sub := make([]byte, subLen)
	putU16(sub[0:2], 4)
	putU16(sub[2:4], uint16(subLen))
	putU16(sub[4:6], 0)                  // language.
	putU16(sub[6:8], uint16(2*segCount)) // segCountX2.
	// Segment 0: U+0041 only. Segment 1: U+0042 only. Sorted ascending.
	putU16(sub[offEndCode+0:offEndCode+2], 0x0041)
	putU16(sub[offEndCode+2:offEndCode+4], 0x0042)
	putU16(sub[offStartCode+0:offStartCode+2], 0x0041)
	putU16(sub[offStartCode+2:offStartCode+4], 0x0042)
	putU16(sub[offIDelta+0:offIDelta+2], 0)
	putU16(sub[offIDelta+2:offIDelta+4], 0)
	// A non-zero idRangeOffset routes the lookup through glyphIdArray rather
	// than applying idDelta directly. The offset is relative to the position of
	// the idRangeOffset field itself and lands on the matching glyph id.
	putU16(sub[offIRangeOffset+0:offIRangeOffset+2],
		uint16(offGlyphArray+0-(offIRangeOffset+0)))
	putU16(sub[offIRangeOffset+2:offIRangeOffset+4],
		uint16(offGlyphArray+2-(offIRangeOffset+2)))
	putU16(sub[offGlyphArray+0:offGlyphArray+2], 1) // 'A' -> glyph 1.
	putU16(sub[offGlyphArray+2:offGlyphArray+4], 2) // 'B' -> glyph 2.

	const tableHeader = 4
	const entrySize = 8
	b := make([]byte, tableHeader+entrySize+subLen)
	putU16(b[0:2], 0) // version.
	putU16(b[2:4], 1) // numSubtables.
	rec := b[tableHeader:]
	putU16(rec[0:2], pidWindows)
	putU16(rec[2:4], psidWindowsUCS2)
	putU32(rec[4:8], tableHeader+entrySize)
	copy(b[tableHeader+entrySize:], sub)
	return b
}

// simpleGlyfSquare builds a simple one-contour glyph: a square with four
// on-curve points. Every coordinate delta is a single positive byte so that
// the four identical flags suffice. The cumulative points are:
//
//	(100, 0), (300, 200), (500, 400), (600, 444)
//
// with xMin=100, yMin=0, xMax=600, yMax=444.
func simpleGlyfSquare() []byte {
	b := make([]byte, 0, 32)
	tmp := make([]byte, 2)

	putU16(tmp, 1) // numContours = 1.
	b = append(b, tmp...)
	for _, v := range []int16{100, 0, 600, 444} { // xMin, yMin, xMax, yMax.
		putU16(tmp, uint16(v))
		b = append(b, tmp...)
	}
	putU16(tmp, 3) // endPtsOfContours[0] = 3.
	b = append(b, tmp...)
	putU16(tmp, 0) // instructionLength = 0.
	b = append(b, tmp...)

	// Four flags: on-curve, short positive X and Y deltas.
	flag := byte(flagOnCurve | flagXShortVector | flagPositiveXShortVector |
		flagYShortVector | flagPositiveYShortVector)
	b = append(b, flag, flag, flag, flag)

	b = append(b, 100, 200, 200, 100) // x deltas.
	b = append(b, 0, 200, 200, 44)    // y deltas.
	return b
}

// compoundGlyf builds a compound glyph consisting of one component referencing
// glyph 2, translated by (25, 40), with no transform. flagMoreComponents is
// clear so the single component terminates the list.
func compoundGlyf() []byte {
	b := make([]byte, 10) // empty glyph header (numContours = -1).
	putU16(b[0:2], 0xffff)
	// Bounding box zeros are acceptable for a compound glyph.
	flags := uint16(flagArg1And2AreWords | flagArgsAreXYValues)
	tmp := make([]byte, 2)
	putU16(tmp, flags)
	b = append(b, tmp...)
	putU16(tmp, 2) // glyphIndex of the component.
	b = append(b, tmp...)
	putU16(tmp, 25) // argument 1 (dx).
	b = append(b, tmp...)
	putU16(tmp, 40) // argument 2 (dy).
	b = append(b, tmp...)
	return b
}

func buildGlyfAndLoca(numGlyphs int, compound bool) (glyf, loca []byte) {
	locations := make([]uint32, numGlyphs+1)
	var glyfData []byte
	for i := 0; i < numGlyphs; i++ {
		locations[i] = uint32(len(glyfData))
		var glyph []byte
		switch {
		case i == 0:
			glyph = nil // .notdef is empty.
		case compound && i == 1:
			glyph = compoundGlyf()
		default:
			glyph = simpleGlyfSquare()
		}
		glyfData = append(glyfData, glyph...)
		// glyf data for each glyph must be 2-byte aligned.
		if len(glyfData)%2 != 0 {
			glyfData = append(glyfData, 0)
		}
	}
	locations[numGlyphs] = uint32(len(glyfData))

	loca = make([]byte, 4*(numGlyphs+1)) // long format.
	for i, off := range locations {
		putU32(loca[4*i:], off)
	}
	return glyfData, loca
}

// buildKern builds a version-0, format-0 horizontal kern table containing one
// pair: glyph 1 + glyph 2 adjust by -40 font units. The layout is:
//
//	4-byte outer header, 6-byte subtable header, 8-byte format-0 body header,
//	then one 6-byte pair record (24 bytes total).
func buildKern() []byte {
	const entrySize = 6
	numPairs := uint16(1)
	subtableLen := uint16(6 + 8 + entrySize*uint16(numPairs))
	b := make([]byte, 4+subtableLen)
	// Outer header.
	putU16(b[0:2], 0) // version 0.
	putU16(b[2:4], 1) // numTables.
	// Subtable header (6 bytes) at offset 4.
	putU16(b[4:6], 0)           // version 0.
	putU16(b[6:8], subtableLen) // subtable length (includes these 6).
	b[8] = 0                    // format 0.
	b[9] = 0x01                 // coverage: horizontal.
	// Format-0 body header (8 bytes) at offset 10.
	putU16(b[10:12], numPairs) // nPairs.
	putU16(b[12:14], 0)        // searchRange.
	putU16(b[14:16], 0)        // entrySelector.
	putU16(b[16:18], 0)        // rangeShift.
	// One pair record at offset 18.
	putU16(b[18:20], 1)        // left glyph.
	putU16(b[20:22], 2)        // right glyph.
	putU16(b[22:24], i16(-40)) // value.
	return b
}

// buildGPOS wraps a PairPos-format-1 subtable in a complete GPOS table using a
// DFLT script and a kern feature, mirroring the layout exercised by
// gpos_test.go. When sub is nil a valid subtable is synthesized.
func buildGPOS(sub []byte) []byte {
	if sub == nil {
		sub = buildValidPairPosSubtable()
	}
	header := []byte{
		// GPOS Header.
		0x00, 0x01, 0x00, 0x00, // Version 1.0.
		0x00, 0x0a, // ScriptListOffset = 10.
		0x00, 0x1e, // FeatureListOffset = 30.
		0x00, 0x2c, // LookupListOffset = 44.

		// Offset 10: ScriptList.
		0x00, 0x01, // scriptCount = 1.
		0x44, 0x46, 0x4c, 0x54, // scriptTag = 'DFLT'.
		0x00, 0x08, // scriptOffset = 8 (Script table at 18).

		// Offset 18: Script table.
		0x00, 0x04, // defaultLangSysOffset = 4 (LangSys at 22).
		0x00, 0x00, // langSysCount = 0.

		// Offset 22: LangSys table.
		0x00, 0x00, // lookupOrder.
		0xff, 0xff, // requiredFeatureIndex = none.
		0x00, 0x01, // featureIndexCount = 1.
		0x00, 0x00, // featureIndices[0] = 0.

		// Offset 30: FeatureList.
		0x00, 0x01, // featureCount = 1.
		0x6b, 0x65, 0x72, 0x6e, // featureTag = 'kern'.
		0x00, 0x08, // featureOffset = 8 (Feature at 38).

		// Offset 38: Feature table.
		0x00, 0x00, // featureParamsOffset.
		0x00, 0x01, // lookupCount = 1.
		0x00, 0x00, // lookupListIndices[0] = 0.

		// Offset 44: LookupList.
		0x00, 0x01, // lookupCount = 1.
		0x00, 0x04, // lookupOffsets[0] = 4 (Lookup at 48).

		// Offset 48: Lookup table.
		0x00, 0x02, // lookupType = 2 (PairPos).
		0x00, 0x00, // lookupFlag.
		0x00, 0x01, // subTableCount = 1.
		0x00, 0x08, // subTableOffsets[0] = 8 (subtable at 56).
	}
	return append(header, sub...)
}

// buildValidPairPosSubtable builds a PairPos format 1 subtable covering glyph
// 1 and kerning the (1, 2) pair by -40 units. Layout (relative to subtable):
//
//	0..9   PairPos header (posFormat, coverageOffset=14, valueFormat1=4,
//	       valueFormat2=0, pairSetCount=1, pairSetOffset[0]=16)
//	10..13 padding
//	14..19 coverage format 1: glyphCount=1, glyphArray=[1]
//	20..21 PairSet 0: pairValueCount=1
//	22..25 PairValueRecord: secondGlyph=2, xAdvance=-40
func buildValidPairPosSubtable() []byte {
	sub := make([]byte, 26)
	putU16(sub[0:2], 1)          // posFormat = 1.
	putU16(sub[2:4], 14)         // coverageOffset.
	putU16(sub[4:6], 0x04)       // valueFormat1 = X_ADVANCE.
	putU16(sub[6:8], 0)          // valueFormat2.
	putU16(sub[8:10], 1)         // pairSetCount.
	putU16(sub[10:12], 20)       // pairSetOffset[0] = 20.
	putU16(sub[14:16], 1)        // coverage format 1.
	putU16(sub[16:18], 1)        // glyphCount = 1.
	putU16(sub[18:20], 1)        // glyphArray[0] = 1.
	putU16(sub[20:22], 1)        // pairValueCount = 1.
	putU16(sub[22:24], 2)        // secondGlyph = 2.
	putU16(sub[24:26], i16(-40)) // xAdvance.
	return sub
}
